// Example Go consumer for the EFE gRPC service.
// Build: cd example && go build .
package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"time"

	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/grpc/metadata"
	"google.golang.org/grpc/status"

	// Generated by deploy/proto-gen/scripts/gen-go.sh — once the SDK
	// module is published, replace with:
	//   efev1 "github.com/efe-project/efe-client-go/efe/mode1/v1"
	efev1 "github.com/efe-project/efe-client-go/efe/mode1/v1"
)

func main() {
	var (
		endpoint = flag.String("endpoint", os.Getenv("EFE_ENDPOINT"), "host:port")
		tenant   = flag.String("tenant", "example-tenant", "tenant id")
		catalog  = flag.String("catalog", "support_triage", "catalog name")
		text     = flag.String("text", "my card was charged without consent", "text to classify")
		useTLS   = flag.Bool("tls", true, "enable TLS (production)")
		caPath   = flag.String("ca", os.Getenv("EFE_TLS_CA"), "CA PEM path")
		token    = flag.String("jwt", os.Getenv("EFE_JWT"), "Bearer JWT")
	)
	flag.Parse()

	if *endpoint == "" {
		log.Fatal("--endpoint or EFE_ENDPOINT required")
	}

	var creds credentials.TransportCredentials
	if *useTLS {
		tc, err := credentials.NewClientTLSFromFile(*caPath, "")
		if err != nil {
			log.Fatalf("tls: %v", err)
		}
		creds = tc
	} else {
		creds = insecure.NewCredentials()
	}

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	conn, err := grpc.DialContext(ctx, *endpoint,
		grpc.WithTransportCredentials(creds),
		grpc.WithBlock(),
	)
	if err != nil {
		log.Fatalf("dial: %v", err)
	}
	defer conn.Close()

	cli := efev1.NewMode1ServiceClient(conn)

	if *token != "" {
		ctx = metadata.AppendToOutgoingContext(ctx,
			"authorization", "Bearer "+*token,
			"x-request-id", fmt.Sprintf("example-%d", time.Now().UnixNano()),
		)
	}

	resp, err := cli.Classify(ctx, &efev1.ClassifyRequest{
		Text:      *text,
		Catalog:   *catalog,
		TenantId:  *tenant,
		RequestId: fmt.Sprintf("example-%d", time.Now().UnixNano()),
	})
	if err != nil {
		s, _ := status.FromError(err)
		log.Fatalf("classify failed: code=%s msg=%s", s.Code(), s.Message())
	}

	fmt.Printf("label:      %s\n", resp.Label)
	fmt.Printf("confidence: %.4f\n", resp.Confidence)
	fmt.Printf("zone:       %s\n", resp.Zone)
	fmt.Printf("rounds:     %d\n", resp.Rounds)
	fmt.Printf("reject:     %t\n", resp.Reject)
	fmt.Printf("served_by:  %s\n", resp.ServedByPod)
}
